"""Gap-fill questions written after the Concept finder's coverage table showed concepts with fewer than 8 bank questions.
Every number is computed here from the formula and every wrong option is a computed common mistake.  Output: data/qsrc/mNN_zgap.json (sorted after the other files so earlier question ids stay stable) (tag 'gap').
Run: python3 -I build/gen/gen_gap.py && python3 build/assemble.py"""
import os, sys, json, math, re, collections
ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), '..', '..'))
TOP = {}
for i in range(1, 11):
    p = os.path.join(ROOT, 'data', 'qbank', f'm{i:02d}.json')
    if os.path.exists(p):
        for it in json.load(open(p, encoding='utf-8'))['items']: TOP[it['topic']['en']] = it['topic']
OUT = collections.defaultdict(list)
def vn(s): return re.sub(r'(?<=\d)\.(?=\d)', ',', s)
def bi(x): return x if isinstance(x, tuple) else (x, x)
def g(x, n=4):
    s = f'{x:.{n}g}'; return s
def Q(mod, topic, q, correct, wrongs, expl, level, src, concept):
    """q, expl, src: (vi, en);  correct / wrongs: str or (vi, en)."""
    opts = [bi(correct)] + [bi(w) for w in wrongs]
    assert len({o[1] for o in opts}) == len(opts) >= 4, (q, opts)
    OUT[mod].append(dict(kind='mcq', q=dict(vi=vn(q[0]), en=q[1]), opts=[dict(vi=o[0], en=o[1]) for o in opts[:4]], correct=0, explain=dict(vi=vn(expl[0]), en=expl[1]), level=level,
                         topic=TOP[topic], src=dict(vi='Bổ sung (lấp khoảng trống độ phủ) – ' + src[0], en='Gap-fill (coverage loop) – ' + src[1]), origin='bo_sung', fixed_order=False, check='script', tags=['gap'], concept=concept))
TC = 'ICs, TTL and CMOS'
# ------------------------------------------------------------------ m01-cmos
def vsp(VDD, VTN, VTP, KR): return (VDD + VTP + VTN * math.sqrt(KR)) / (1 + math.sqrt(KR))
S = ('Jaeger 5e §6.11, 7.1–7.3', 'Jaeger 5e §6.11, 7.1–7.3')
Q('m01', TC, ('Trong bộ đảo CMOS với ngõ vào ở mức thấp (0 V), transistor nào dẫn và ngõ ra bằng bao nhiêu?', 'In a CMOS inverter with the input LOW (0 V), which transistor conducts and what is the output?'),
  ('PMOS dẫn, NMOS tắt; ngõ ra ≈ VDD', 'The PMOS conducts and the NMOS is off; output ≈ VDD'), [('NMOS dẫn, PMOS tắt; ngõ ra ≈ VDD', 'The NMOS conducts and the PMOS is off; output ≈ VDD'), ('PMOS dẫn, NMOS tắt; ngõ ra ≈ 0 V', 'The PMOS conducts and the NMOS is off; output ≈ 0 V'), ('Cả hai cùng dẫn mạnh; ngõ ra ≈ VDD/2', 'Both conduct strongly; output ≈ VDD/2')],
  ('Ngõ vào thấp làm VGS của PMOS = −VDD (bật) còn NMOS có VGS = 0 (tắt), nên PMOS kéo ngõ ra lên VDD.', 'A LOW input gives the PMOS VGS = −VDD (on) and the NMOS VGS = 0 (off), so the PMOS pulls the output up to VDD.'), 1, S, 'm01-cmos')
Q('m01', TC, ('Vì sao bộ đảo CMOS có công suất tĩnh gần bằng 0?', 'Why does a CMOS inverter have almost zero static power?'),
  ('Ở trạng thái ổn định luôn có một transistor tắt nên không có đường dòng từ nguồn xuống đất', 'In a steady state one transistor is always off, so there is no dc path from the supply to ground'), [('Điện trở tải rất lớn nên dòng rất nhỏ', 'The load resistor is very large so the current is tiny'), ('Điện áp nguồn của CMOS luôn bằng 0', 'The CMOS supply voltage is always zero'), ('Cả NMOS và PMOS đều luôn dẫn một chút', 'Both the NMOS and the PMOS always conduct a little')],
  ('Chỉ khi chuyển trạng thái, cả hai transistor cùng dẫn trong thời gian ngắn và tụ tải được nạp/xả: đó là công suất động.', 'Only while switching do both conduct briefly and the load capacitance charges/discharges: that is the dynamic power.'), 1, S, 'm01-cmos')
for VDD, VTN, VTP, KR in [(3.3, 0.7, -0.7, 1.0), (5.0, 1.0, -1.0, 1.0)]:
    v = vsp(VDD, VTN, VTP, KR); assert abs(v - VDD / 2) < 1e-12
    Q('m01', TC, (f'Bộ đảo CMOS đối xứng có VDD = {g(VDD)} V, VTN = {g(VTN)} V, VTP = −{g(-VTP)} V và KR = Kn/Kp = 1. Ngưỡng chuyển mạch VSP là bao nhiêu?', f'A symmetric CMOS inverter has VDD = {g(VDD)} V, VTN = {g(VTN)} V, VTP = −{g(-VTP)} V and KR = Kn/Kp = 1. What is the switching threshold VSP?'),
      f'{g(v)} V', [f'{g(v + VTN)} V', f'{g(v - VTN)} V', f'{g(VDD)} V'],
      (f'VSP = (VDD + VTP + VTN·√KR)/(1 + √KR) = ({g(VDD)} − {g(-VTP)} + {g(VTN)})/2 = {g(v)} V = VDD/2.', f'VSP = (VDD + VTP + VTN·√KR)/(1 + √KR) = ({g(VDD)} − {g(-VTP)} + {g(VTN)})/2 = {g(v)} V = VDD/2.'), 2, S, 'm01-cmos')
VDD, VTN, VTP, KR = 2.5, 0.5, -0.5, 4.0; v = vsp(VDD, VTN, VTP, KR); assert abs(v - 1.0) < 1e-12
Q('m01', TC, ('Bộ đảo CMOS có VDD = 2,5 V, VTN = 0,5 V, VTP = −0,5 V và KR = Kn/Kp = 4. Ngưỡng chuyển mạch VSP là bao nhiêu?', 'A CMOS inverter has VDD = 2.5 V, VTN = 0.5 V, VTP = −0.5 V and KR = Kn/Kp = 4. What is the switching threshold VSP?'),
  '1.00 V', [f'{g(VDD / 2, 3)} V', f'{g((VDD + VTP + VTN * KR) / (1 + KR), 3)} V', f'{g((VDD + VTP + VTN) / (1 + math.sqrt(KR)), 3)} V'],
  ('√KR = 2 nên VSP = (2,5 − 0,5 + 0,5·2)/(1 + 2) = 3/3 = 1,00 V. KR lớn nghĩa là NMOS mạnh hơn, ngưỡng thấp hơn VDD/2. Lỗi hay gặp: quên căn bậc hai của KR.', '√KR = 2 so VSP = (2.5 − 0.5 + 0.5·2)/(1 + 2) = 3/3 = 1.00 V. A larger KR means a stronger NMOS and a threshold below VDD/2. Common slip: leaving out the square root of KR.'), 2, S, 'm01-cmos')
Q('m01', TC, ('Nếu tăng Kn (NMOS mạnh hơn) và giữ nguyên các thông số khác, ngưỡng chuyển mạch VSP của bộ đảo CMOS thay đổi thế nào?', 'If Kn is increased (a stronger NMOS) with everything else unchanged, how does the CMOS inverter switching threshold VSP change?'),
  ('VSP giảm (dịch về phía mức thấp)', 'VSP decreases (moves toward the low level)'), [('VSP tăng', 'VSP increases'), ('VSP không đổi vì chỉ phụ thuộc VDD', 'VSP is unchanged because it depends only on VDD'), ('VSP tăng đúng bằng tỉ lệ Kn', 'VSP rises in proportion to Kn')],
  ('VSP = (VDD + VTP + VTN√KR)/(1 + √KR) giảm khi KR tăng (với VTN < VDD + VTP).', 'VSP = (VDD + VTP + VTN√KR)/(1 + √KR) falls as KR rises (when VTN < VDD + VTP).'), 2, S, 'm01-cmos')
C, V, f = 0.5e-12, 2.5, 100e6; P = C * V * V * f; assert abs(P - 312.5e-6) < 1e-12
Q('m01', TC, ('Một bộ đảo CMOS tải C = 0,5 pF, VDD = 2,5 V chuyển trạng thái ở f = 100 MHz. Công suất động P = C·V²·f là bao nhiêu?', 'A CMOS inverter drives C = 0.5 pF at VDD = 2.5 V and switches at f = 100 MHz. What is the dynamic power P = C·V²·f?'),
  '312.5 μW', ['125 μW', '625 μW', '31.25 μW'],
  (f'P = 0,5·10⁻¹² × 2,5² × 10⁸ = {g(P * 1e6, 4)} μW. Công suất tỉ lệ với bình phương điện áp nguồn.', f'P = 0.5·10⁻¹² × 2.5² × 10⁸ = {g(P * 1e6, 4)} μW. The power scales with the square of the supply voltage.'), 1, S, 'm01-cmos')
Q('m01', TC, ('Nếu giảm một nửa điện áp nguồn VDD của một bộ đảo CMOS (giữ nguyên C và f), công suất động thay đổi thế nào?', 'If the supply VDD of a CMOS inverter is halved (C and f unchanged), how does the dynamic power change?'),
  ('Giảm 4 lần', 'It falls by a factor of 4'), [('Giảm 2 lần', 'It falls by a factor of 2'), ('Giảm 8 lần', 'It falls by a factor of 8'), ('Không đổi', 'It does not change')],
  ('P = C·V²·f tỉ lệ V², nên V → V/2 cho P → P/4.', 'P = C·V²·f is proportional to V², so V → V/2 gives P → P/4.'), 1, S, 'm01-cmos')
tp = (0.4e-9 + 0.6e-9) / 2; PDP = P * 1e-9
Q('m01', TC, ('Một cổng CMOS có thời gian trễ tPHL = 0,4 ns và tPLH = 0,6 ns. Trễ truyền trung bình τp là bao nhiêu?', 'A CMOS gate has delays tPHL = 0.4 ns and tPLH = 0.6 ns. What is the average propagation delay τp?'),
  '0.5 ns', ['1.0 ns', '0.2 ns', '0.24 ns'],
  ('τp = (tPHL + tPLH)/2 = (0,4 + 0,6)/2 = 0,5 ns.', 'τp = (tPHL + tPLH)/2 = (0.4 + 0.6)/2 = 0.5 ns.'), 1, S, 'm01-cmos')
Q('m01', TC, ('Một cổng có công suất trung bình P = 312,5 μW và trễ truyền τp = 1 ns. Tích công suất–trễ (PDP = P·τp) là bao nhiêu?', 'A gate has an average power P = 312.5 μW and a propagation delay τp = 1 ns. What is the power–delay product (PDP = P·τp)?'),
  f'{g(PDP * 1e12, 4)} pJ', ['312.5 pJ', '3.125 pJ', '0.03125 pJ'],
  ('PDP = 312,5·10⁻⁶ W × 10⁻⁹ s = 3,125·10⁻¹³ J = 0,3125 pJ.', 'PDP = 312.5·10⁻⁶ W × 10⁻⁹ s = 3.125·10⁻¹³ J = 0.3125 pJ.'), 2, S, 'm01-cmos')
Q('m01', TC, ('Khi vIN bằng đúng ngưỡng chuyển mạch VSP của bộ đảo CMOS, hai transistor ở trạng thái nào?', 'When vIN equals exactly the switching threshold VSP of a CMOS inverter, what are the two transistors doing?'),
  ('Cả hai ở vùng bão hoà và ngõ ra đang chuyển nhanh', 'Both are in saturation and the output is switching steeply'), [('NMOS ở vùng cắt, PMOS ở vùng tuyến tính', 'The NMOS is cut off and the PMOS is in the triode region'), ('Cả hai ở vùng cắt', 'Both are cut off'), ('Cả hai ở vùng tuyến tính', 'Both are in the triode region')],
  ('VSP được định nghĩa khi vIN = vOUT; khi đó dòng hai transistor bằng nhau trong vùng bão hoà và độ lợi của bộ đảo cực lớn.', 'VSP is defined where vIN = vOUT; the two saturation currents are equal there and the inverter gain is very large.'), 3, S, 'm01-cmos')
