Q('m01', 'Op-amp circuits in the logic context', ('Một op-amp không hồi tiếp có V₊ = 2 mV và V₋ = 0, nguồn ±13 V và Aol = 10⁵. Ngõ ra là bao nhiêu?', 'An open-loop op-amp has V₊ = 2 mV and V₋ = 0, supplies of ±13 V and Aol = 10⁵. What is the output?'),
  ('Bão hoà ở khoảng +13 V', 'Saturated at about +13 V'), ['+200 V', '+2 mV', '0 V'],
  ('Aol·(V₊ − V₋) = 10⁵ × 2 mV = 200 V vượt xa nguồn, nên ngõ ra bão hoà ở mức nguồn dương (mạch so sánh).', 'Aol·(V₊ − V₋) = 10⁵ × 2 mV = 200 V is far beyond the supply, so the output saturates at the positive supply (comparator action).'), 1, ('EASA M04 SM01 Q1-35…1-38', 'EASA M04 SM01 Q1-35…1-38'), 'm01-opamp-logic')
Q('m01', 'Op-amp circuits in the logic context', ('Mạch op-amp nào làm cầu nối giữa tín hiệu tương tự và mức logic số?', 'Which op-amp circuit bridges an analog signal to digital logic levels?'),
  ('Mạch so sánh (comparator)', 'The comparator'), [('Mạch tích phân', 'The integrator'), ('Mạch vi phân', 'The differentiator'), ('Mạch lặp điện áp', 'The voltage follower')],
  ('Mạch so sánh có ngõ ra chỉ hai mức bão hoà, phù hợp với mức logic cao/thấp.', 'The comparator has only two saturated output levels, which match logic HIGH/LOW.'), 1, ('EASA M04 SM01 Q1-35…1-38', 'EASA M04 SM01 Q1-35…1-38'), 'm01-opamp-logic')
Q('m01', 'Op-amp circuits in the logic context', ('Mạch lặp điện áp dùng op-amp được cấp 3 V ở ngõ vào. Ngõ ra là bao nhiêu và độ lợi là bao nhiêu?', 'A voltage follower built with an op-amp receives 3 V at its input. What are the output and the gain?'),
  ('3 V, độ lợi 1', '3 V, gain 1'), [('6 V, độ lợi 2', '6 V, gain 2'), ('−3 V, độ lợi −1', '−3 V, gain −1'), ('0 V, độ lợi 0', '0 V, gain 0')],
  ('Ngõ ra nối thẳng về ngõ vào đảo nên Acl = 1 và cùng pha: Vout = Vin.', 'The output is wired straight to the inverting input so Acl = 1 and in phase: Vout = Vin.'), 1, ('EASA M04 SM01 Q1-35…1-38', 'EASA M04 SM01 Q1-35…1-38'), 'm01-opamp-logic')
AC = 'Adders and combinational circuits'; E = ('EASA M04 SM01 (encoders, decoders)', 'EASA M04 SM01 (encoders, decoders)')
Q('m01', AC, ('Một bộ giải mã (decoder) có 4 ngõ vào mã thì có bao nhiêu ngõ ra?', 'How many outputs does a decoder with 4 code inputs have?'),
  '16', ['4', '8', '15'], ('n ngõ vào mã cho 2ⁿ ngõ ra: 2⁴ = 16.', 'n code inputs give 2ⁿ outputs: 2⁴ = 16.'), 1, E, 'm01-combinational')
