CP = 'Converters and peak detector'; F5 = ('Floyd 9e §14–5', 'Floyd 9e §14–5')
Q('m05', CP, ('Bộ chuyển đổi điện áp sang dòng (V-to-I) dùng op-amp có Vin = 5 V và R1 = 10 kΩ. Dòng qua tải là bao nhiêu?', 'A voltage-to-current (V-to-I) converter built with an op-amp has Vin = 5 V and R1 = 10 kΩ. What is the load current?'),
  '0.5 mA', ['5 mA', '50 μA', '0.05 mA'], ('Hồi tiếp âm ép điện áp trên R1 bằng Vin nên I = Vin/R1 = 5/10 000 = 0,5 mA.', 'Negative feedback forces the voltage across R1 to equal Vin, so I = Vin/R1 = 5/10,000 = 0.5 mA.'), 1, F5, 'm05-v-i')
Q('m05', CP, ('Trong bộ chuyển đổi V-to-I, tải tăng từ 1 kΩ lên 2 kΩ (vẫn trong dải tuân thủ). Dòng tải thay đổi thế nào?', 'In a V-to-I converter the load rises from 1 kΩ to 2 kΩ (still within the compliance range). How does the load current change?'),
  ('Không đổi vì I = Vin/R1', 'It does not change because I = Vin/R1'), [('Giảm một nửa', 'It halves'), ('Tăng gấp đôi', 'It doubles'), ('Giảm 4 lần', 'It falls by a factor of 4')], ('Dòng chỉ phụ thuộc Vin và R1, không phụ thuộc giá trị tải: đây là nguồn dòng không đổi.', 'The current depends only on Vin and R1, not on the load value: this is a constant-current source.'), 1, F5, 'm05-v-i')
Vsat, I, R1 = 10.0, 2e-3, 1e3; RLmax = Vsat / I - R1; assert RLmax == 4000.0
Q('m05', CP, ('Nguồn dòng V-to-I có tải nằm trong vòng hồi tiếp, R1 = 1 kΩ, dòng đặt 2 mA và op-amp bão hoà ở ±10 V. Điện trở tải lớn nhất còn giữ dòng không đổi (dải tuân thủ) là bao nhiêu?', 'A V-to-I current source has the load in the feedback loop, R1 = 1 kΩ, a set current of 2 mA and an op-amp that saturates at ±10 V. What is the largest load resistance that still keeps the current constant (compliance range)?'),
  '4 kΩ', ['5 kΩ', '10 kΩ', '3 kΩ'], ('Vout = I·(RL + R1) ≤ 10 V nên RL ≤ 10/0,002 − 1000 = 4 kΩ; quá giá trị đó op-amp bão hoà và dòng không còn không đổi.', 'Vout = I·(RL + R1) ≤ 10 V so RL ≤ 10/0.002 − 1000 = 4 kΩ; beyond that the op-amp saturates and the current is no longer constant.'), 3, F5, 'm05-v-i')
Q('m05', CP, ('Bộ chuyển đổi dòng sang điện áp (I-to-V) có Iin = 50 μA và Rf = 22 kΩ. Điện áp ra là bao nhiêu?', 'A current-to-voltage (I-to-V) converter has Iin = 50 μA and Rf = 22 kΩ. What is the output voltage?'),
  '−1.1 V', ['+1.1 V', '−0.0023 V', '−11 V'], ('Vout = −Iin·Rf = −50·10⁻⁶ × 22·10³ = −1,1 V.', 'Vout = −Iin·Rf = −50·10⁻⁶ × 22·10³ = −1.1 V.'), 1, F5, 'm05-v-i')
Q('m05', CP, ('Cần bộ chuyển đổi I-to-V cho điện áp ra −5 V khi Iin = 20 μA. Giá trị Rf là bao nhiêu?', 'An I-to-V converter must give −5 V when Iin = 20 μA. What is Rf?'),
  '250 kΩ', ['25 kΩ', '100 kΩ', '2.5 MΩ'], ('Rf = |Vout|/Iin = 5/(20·10⁻⁶) = 250 kΩ.', 'Rf = |Vout|/Iin = 5/(20·10⁻⁶) = 250 kΩ.'), 2, F5, 'm05-v-i')
Q('m05', CP, ('Vì sao dòng tải của nguồn dòng V-to-I không phụ thuộc giá trị tải?', 'Why is the load current of a V-to-I current source independent of the load value?'),
  ('Hồi tiếp âm ép điện áp trên R1 bằng Vin', 'Negative feedback forces the voltage across R1 to equal Vin'), [('Tải được nối nối tiếp với một nguồn áp lý tưởng', 'The load is in series with an ideal voltage source'), ('Op-amp không có dòng ra', 'The op-amp has no output current'), ('R1 luôn bằng tải', 'R1 always equals the load')], ('Điện áp trên R1 bằng Vin cố định nên dòng I = Vin/R1 cố định; op-amp tự điều chỉnh điện áp ra để đẩy dòng đó qua tải.', 'The voltage across R1 is held at Vin, so I = Vin/R1 is fixed; the op-amp adjusts its output voltage to push that current through the load.'), 2, F5, 'm05-v-i')
Q('m05', CP, ('Trong bộ chuyển đổi V-to-I với Vin = 2 V, tăng R1 từ 1 kΩ lên 2 kΩ. Dòng tải đổi từ bao nhiêu sang bao nhiêu?', 'In a V-to-I converter with Vin = 2 V, R1 is raised from 1 kΩ to 2 kΩ. The load current changes from what to what?'),
  ('Từ 2 mA xuống 1 mA', 'From 2 mA to 1 mA'), [('Từ 2 mA lên 4 mA', 'From 2 mA to 4 mA'), ('Từ 1 mA xuống 0,5 mA', 'From 1 mA to 0.5 mA'), ('Không đổi', 'No change')], ('I = Vin/R1: 2/1000 = 2 mA, rồi 2/2000 = 1 mA.', 'I = Vin/R1: 2/1000 = 2 mA, then 2/2000 = 1 mA.'), 1, F5, 'm05-v-i')
Q('m05', CP, ('Một mạch tách đỉnh (peak detector) dùng op-amp và điốt nhận sóng sin đỉnh 3,2 V (điốt nằm trong vòng hồi tiếp). Điện áp tụ giữ ở trạng thái ổn định là bao nhiêu?', 'A peak detector built with an op-amp and a diode receives a sine of 3.2 V peak (the diode is inside the feedback loop). What voltage does the hold capacitor reach?'),
  '3.2 V', ['2.5 V', '3.9 V', '0 V'], ('Điốt nằm trong vòng hồi tiếp nên sụt áp 0,7 V được bù: tụ nạp tới đúng giá trị đỉnh 3,2 V.', 'The diode is inside the feedback loop so its 0.7 V drop is compensated: the capacitor charges to exactly the peak value 3.2 V.'), 2, F5, 'm05-peak')
Q('m05', CP, ('Mạch tách đỉnh dùng op-amp giữ giá trị nào của tín hiệu vào?', 'Which value of the input does an op-amp peak detector hold?'),
  ('Giá trị đỉnh lớn nhất đã xuất hiện', 'The largest peak value that has occurred'), [('Giá trị trung bình', 'The average value'), ('Giá trị tức thời hiện tại', 'The present instantaneous value'), ('Giá trị đỉnh–đỉnh', 'The peak-to-peak value')], ('Tụ chỉ được nạp khi Vin lớn hơn điện áp đang giữ, nên nó ghi nhớ đỉnh cao nhất tới khi bị xả.', 'The capacitor charges only when Vin exceeds the held voltage, so it remembers the highest peak until it is discharged.'), 1, F5, 'm05-peak')
Q('m05', CP, ('Vì sao trong mạch tách đỉnh dùng op-amp, điốt được đặt trong vòng hồi tiếp của op-amp?', 'Why is the diode placed inside the op-amp feedback loop in an op-amp peak detector?'),
  ('Để sụt áp thuận 0,7 V của điốt được bù', 'So the diode\'s 0.7 V forward drop is compensated'), [('Để tăng điện áp đỉnh thêm 0,7 V', 'To raise the peak voltage by 0.7 V'), ('Để tụ xả nhanh hơn', 'So the capacitor discharges faster'), ('Để op-amp hoạt động như mạch tích phân', 'So the op-amp acts as an integrator')], ('Op-amp tự nâng điện áp ra thêm 0,7 V để điốt dẫn, nên điện áp tụ bằng đúng Vin.', 'The op-amp raises its output by 0.7 V so the diode conducts, so the capacitor voltage equals Vin exactly.'), 2, F5, 'm05-peak')
Q('m05', CP, ('Làm thế nào để đưa mạch tách đỉnh về trạng thái ban đầu, sẵn sàng đo đỉnh mới?', 'How do you reset a peak detector so it can measure a new peak?'),
  ('Xả tụ giữ (ví dụ bằng một công tắc)', 'Discharge the hold capacitor (for example with a switch)'), [('Đảo cực nguồn', 'Reverse the supply polarity'), ('Tăng điện áp vào', 'Raise the input voltage'), ('Thay điốt bằng điện trở', 'Replace the diode by a resistor')], ('Tụ giữ đỉnh cho tới khi bị xả; xả tụ đưa ngõ ra về 0.', 'The capacitor holds the peak until it is discharged; discharging it returns the output to zero.'), 2, F5, 'm05-peak')
FA = ('Jaeger 5e §12.5–12.6', 'Jaeger 5e §12.5–12.6'); ADC8 = 5 / 2 ** 8; LSB10 = 5 / 2 ** 10; assert int(round(3 / LSB10)) == 614
Q('m05', CP, ('Bộ ADC 8 bit có thang đo đầy đủ VFS = 5 V. Một LSB (bước mã) bằng bao nhiêu?', 'An 8-bit ADC has a full-scale range VFS = 5 V. How large is one LSB (code step)?'),
  f'{g(ADC8 * 1e3, 4)} mV', [f'{g(5 / 255 * 1e3, 4)} mV', f'{g(5 / 2 ** 10 * 1e3, 4)} mV', f'{g(5 / 8 * 1e3, 4)} mV'], ('LSB = VFS/2ⁿ = 5/256 = 19,53 mV (không phải 5/255).', 'LSB = VFS/2ⁿ = 5/256 = 19.53 mV (not 5/255).'), 1, FA, 'm05-adc-dac')
Q('m05', CP, ('Bộ ADC 10 bit với VFS = 5 V nhận điện áp vào 3 V. Mã số nguyên gần nhất là bao nhiêu?', 'A 10-bit ADC with VFS = 5 V receives 3 V. What is the nearest integer code?'),
  '614', ['768', '600', '512'], ('LSB = 5/1024 = 4,883 mV; 3/0,004883 = 614,4 → mã 614.', 'LSB = 5/1024 = 4.883 mV; 3/0.004883 = 614.4 → code 614.'), 2, FA, 'm05-adc-dac')
Q('m05', CP, ('Bộ ADC 12 bit có VFS = 10 V. Sai số lượng tử tối đa (±½ LSB) là bao nhiêu?', 'A 12-bit ADC has VFS = 10 V. What is the maximum quantisation error (±½ LSB)?'),
  f'{g(10 / 2 ** 12 / 2 * 1e3, 3)} mV', [f'{g(10 / 2 ** 12 * 1e3, 3)} mV', f'{g(10 / 2 ** 14 * 1e3, 3)} mV', f'{g(10 / 12 / 2 * 1e3, 3)} mV'], ('LSB = 10/4096 = 2,441 mV; sai số lượng tử tối đa là nửa LSB = 1,22 mV.', 'LSB = 10/4096 = 2.441 mV; the maximum quantisation error is half an LSB = 1.22 mV.'), 2, FA, 'm05-adc-dac')
Q('m05', CP, ('Bộ ADC 12 bit có bao nhiêu mức (mã) khác nhau?', 'How many different levels (codes) does a 12-bit ADC have?'),
  '4096', ['4095', '144', '2048'], ('2¹² = 4096 mức, từ mã 0 tới 4095.', '2¹² = 4096 levels, from code 0 to 4095.'), 1, FA, 'm05-adc-dac')
Q('m05', CP, ('Bộ ADC xấp xỉ liên tiếp (SAR) 12 bit chạy với đồng hồ f_C = 1 MHz. Thời gian chuyển đổi n/f_C là bao nhiêu?', 'A 12-bit successive-approximation (SAR) ADC runs from a clock f_C = 1 MHz. What is the conversion time n/f_C?'),
  '12 μs', ['4096 μs', '1 μs', '24 μs'], ('SAR cần đúng n = 12 chu kỳ đồng hồ: 12/10⁶ = 12 μs.', 'A SAR needs exactly n = 12 clock cycles: 12/10⁶ = 12 μs.'), 2, FA, 'm05-adc-dac')
vo = 5 * (0.5 + 0.125); assert vo == 3.125
Q('m05', CP, ('DAC 4 bit có VFS = 5 V, mã vào 1010₂. Điện áp ra v_O = VFS·Σ bᵢ·2⁻ⁱ là bao nhiêu?', 'A 4-bit DAC has VFS = 5 V and the input code 1010₂. What is the output v_O = VFS·Σ bᵢ·2⁻ⁱ?'),
  '3.125 V', ['2.5 V', '3.333 V', '1.875 V'], ('1010₂ = 0,5 + 0,125 = 0,625 của thang đo; 0,625 × 5 V = 3,125 V.', '1010₂ = 0.5 + 0.125 = 0.625 of full scale; 0.625 × 5 V = 3.125 V.'), 2, FA, 'm05-adc-dac')
n = math.ceil(math.log2(5 / 1e-3)); assert n == 13 and 5 / 2 ** 12 > 1e-3 >= 5 / 2 ** 13
Q('m05', CP, ('Cần bộ ADC có LSB không lớn hơn 1 mV với VFS = 5 V. Cần ít nhất bao nhiêu bit?', 'An ADC needs an LSB of no more than 1 mV with VFS = 5 V. What is the minimum number of bits?'),
  '13', ['12', '10', '14'], ('2ⁿ ≥ 5/0,001 = 5000: 2¹² = 4096 chưa đủ (LSB 1,22 mV), 2¹³ = 8192 đủ (LSB 0,61 mV).', '2ⁿ ≥ 5/0.001 = 5000: 2¹² = 4096 is not enough (LSB 1.22 mV), 2¹³ = 8192 is (LSB 0.61 mV).'), 3, FA, 'm05-adc-dac')
# ------------------------------------------------------------------ m10 PWM, m07 relaxation, m08 heat
SP = 'Servo loops and components'; FP = ('Floyd 9e §9–4, §16–6', 'Floyd 9e §9–4, §16–6')
Q('m10', SP, ('Xung PWM 12 V có chu kỳ làm việc (duty) 40 % đặt lên servomotor. Điện áp trung bình là bao nhiêu?', 'A 12 V PWM pulse train with a 40 % duty cycle drives a servomotor. What is the average voltage?'),
  '4.8 V', ['12 V', '7.2 V', '0.48 V'], ('Điện áp trung bình = duty × V = 0,40 × 12 = 4,8 V.', 'The average voltage = duty × V = 0.40 × 12 = 4.8 V.'), 1, FP, 'm10-pwm')
Q('m10', SP, ('Để tăng tốc độ servomotor điều khiển bằng PWM mà không đổi biên độ xung, cần làm gì?', 'To make a PWM-driven servomotor run faster without changing the pulse amplitude, what must be done?'),
  ('Tăng chu kỳ làm việc (duty cycle)', 'Increase the duty cycle'), [('Giảm duty cycle', 'Decrease the duty cycle'), ('Giảm biên độ xung', 'Reduce the pulse amplitude'), ('Đảo cực xung', 'Reverse the pulse polarity')], ('Duty cao hơn nghĩa là điện áp trung bình đặt lên động cơ cao hơn, nên động cơ quay nhanh hơn.', 'A higher duty cycle means a higher average voltage on the motor, so it turns faster.'), 1, FP, 'm10-pwm')
R1, R2 = 1e3, 10e3; duty = (R1 + R2) / (R1 + 2 * R2); avg = 12 * duty; assert abs(duty - 11 / 21) < 1e-12
Q('m10', SP, ('555 phi ổn có R1 = 1 kΩ, R2 = 10 kΩ cấp xung biên độ 12 V cho một servomotor qua mạch lái. Duty cycle và điện áp trung bình của xung là bao nhiêu?', 'An astable 555 with R1 = 1 kΩ, R2 = 10 kΩ supplies 12 V pulses to a servomotor through a driver. What are the duty cycle and the average pulse voltage?'),
  f'{g(duty * 100, 3)} %, {g(avg, 3)} V', [f'{g(R2 / (R1 + R2) * 100, 3)} %, {g(12 * R2 / (R1 + R2), 3)} V', f'{g(R1 / (R1 + 2 * R2) * 100, 3)} %, {g(12 * R1 / (R1 + 2 * R2), 3)} V', '50 %, 6 V'],
  ('duty = (R1 + R2)/(R1 + 2R2) = 11/21 = 52,4 %; V_tb = 0,524 × 12 = 6,29 V. (Floyd không có mạch 555 lái servo; đây là phép tính ứng dụng.)', 'duty = (R1 + R2)/(R1 + 2R2) = 11/21 = 52.4 %; Vavg = 0.524 × 12 = 6.29 V. (Floyd has no 555 circuit that drives a servo; this is an application calculation.)'), 3, FP, 'm10-pwm')
Q('m10', SP, ('Điều chế độ rộng xung (PWM) điều khiển động cơ bằng cách thay đổi đại lượng nào của xung?', 'Pulse-width modulation (PWM) controls a motor by changing which property of the pulses?'),
  ('Độ rộng xung (duty cycle), biên độ giữ nguyên', 'The pulse width (duty cycle) while the amplitude stays fixed'), [('Biên độ xung', 'The pulse amplitude'), ('Pha của nguồn', 'The phase of the supply'), ('Số cực của động cơ', 'The number of motor poles')], ('PWM đổi điện áp trung bình bằng độ rộng xung, nên công suất tiêu tán trên phần tử đóng cắt rất thấp.', 'PWM changes the average voltage through the pulse width, so the dissipation in the switching device is very low.'), 1, FP, 'm10-pwm')
# m10 resolver
DR = 'Differential, control synchros and resolvers'; FR = ('EASA M04 SM03 p.3.9', 'EASA M04 SM03 p.3.9')
Q('m10', DR, ('Một resolver có bao nhiêu cuộn stato và chúng đặt lệch nhau bao nhiêu độ?', 'How many stator windings does a resolver have and how far apart are they?'),
  ('Hai cuộn, lệch 90°', 'Two windings, 90° apart'), [('Ba cuộn, lệch 120°', 'Three windings, 120° apart'), ('Hai cuộn, lệch 180°', 'Two windings, 180° apart'), ('Một cuộn', 'One winding')], ('Resolver có hai cuộn stato lệch 90° cho điện áp ∝ sin θ và cos θ; synchro mới có ba cuộn lệch 120°.', 'The resolver has two stator windings 90° apart giving voltages ∝ sin θ and cos θ; it is the synchro that has three windings 120° apart.'), 1, FR, 'm10-resolver')
th1 = math.degrees(math.atan2(0.5, 0.866)); th2 = math.degrees(math.atan2(0.7071, -0.7071)); assert abs(th1 - 30) < 0.01 and abs(th2 - 135) < 0.01
Q('m10', DR, ('Hai cuộn của resolver cho điện áp ∝ sin θ = 0,5 và ∝ cos θ = 0,866 (cùng hệ số tỉ lệ). Góc rôto θ là bao nhiêu?', 'The two windings of a resolver give voltages ∝ sin θ = 0.5 and ∝ cos θ = 0.866 (same scale factor). What is the rotor angle θ?'),
  '30°', ['60°', '45°', '150°'], ('θ = atan2(sin θ, cos θ) = atan2(0,5; 0,866) = 30°.', 'θ = atan2(sin θ, cos θ) = atan2(0.5, 0.866) = 30°.'), 2, FR, 'm10-resolver')
Q('m10', DR, ('Một resolver cho ∝ sin θ = +0,707 và ∝ cos θ = −0,707. Góc rôto là bao nhiêu (trên vòng tròn 0–360°)?', 'A resolver gives ∝ sin θ = +0.707 and ∝ cos θ = −0.707. What is the rotor angle (on the 0–360° circle)?'),
  '135°', ['45°', '225°', '315°'], ('Sin dương, cos âm nên góc nằm ở góc phần tư thứ hai: θ = atan2(0,707; −0,707) = 135° (không phải 45°). Hai điện áp xác định duy nhất góc trên cả vòng tròn.', 'Positive sine and negative cosine put the angle in the second quadrant: θ = atan2(0.707, −0.707) = 135° (not 45°). The two voltages identify the angle uniquely over the whole circle.'), 3, FR, 'm10-resolver')
Q('m10', DR, ('Theo EASA, thiết bị đo góc nào bền nhất và ngõ ra sin/cos của nó thường được đưa tới đâu cho máy tính bay?', 'According to EASA, which angular-measurement device is the most robust and where do its sin/cos outputs usually go for the flight computers?'),
  ('Resolver; bộ chuyển đổi A/D', 'The resolver; an analog-to-digital converter'), [('Biến trở; bộ khuếch đại công suất', 'A potentiometer; a power amplifier'), ('Synchro DC selsyn; bộ so sánh', 'The DC selsyn; a comparator'), ('LVDT; bộ lọc thông thấp', 'The LVDT; a low-pass filter')], ('Resolver là thiết bị đo góc bền nhất; điện áp sin và cos được số hoá bằng ADC cho máy tính bay.', 'The resolver is the most robust angular-measurement device; its sine and cosine voltages are digitised by an ADC for the flight computers.'), 2, FR, 'm10-resolver')
# m07 relaxation
R7, C7, R1_, R2_ = 10e3, 10e-9, 10e3, 10e3; B = R2_ / (R1_ + R2_); f7 = 1 / (2 * R7 * C7 * math.log((1 + B) / (1 - B)))
RT = 'Relaxation oscillators'; F7 = ('Floyd 9e §16–5', 'Floyd 9e §16–5')
Q('m07', RT, ('Bộ dao động thư giãn op-amp có R1 = R2 = 10 kΩ (B = 0,5), R = 10 kΩ và C = 10 nF. Tần số f = 1/(2RC·ln((1+B)/(1−B))) là bao nhiêu?', 'An op-amp relaxation oscillator has R1 = R2 = 10 kΩ (B = 0.5), R = 10 kΩ and C = 10 nF. What is f = 1/(2RC·ln((1+B)/(1−B)))?'),
  f'{g(f7 / 1e3, 3)} kHz', [f'{g(1 / (2 * R7 * C7) / 1e3, 3)} kHz', f'{g(1 / (R7 * C7 * math.log(3)) / 1e3, 3)} kHz', f'{g(1 / (2 * R7 * C7 * math.log(2)) / 1e3, 3)} kHz'],
  (f'(1+B)/(1−B) = 3, ln 3 = 1,0986 nên f = 1/(2 × 10⁻⁴ × 1,0986) = {g(f7 / 1e3, 3)} kHz.', f'(1+B)/(1−B) = 3, ln 3 = 1.0986 so f = 1/(2 × 10⁻⁴ × 1.0986) = {g(f7 / 1e3, 3)} kHz.'), 3, F7, 'm07-relaxation')
Q('m07', RT, ('Ngõ ra của một bộ dao động thư giãn dùng op-amp có hysteresis và mạch RC là dạng sóng nào?', 'What waveform appears at the output of a relaxation oscillator made of an op-amp with hysteresis and an RC circuit?'),
  ('Sóng vuông, còn điện áp tụ có dạng cong nạp–xả giữa hai ngưỡng', 'A square wave, while the capacitor voltage is a charge–discharge curve between the two thresholds'), [('Sóng sin thuần', 'A pure sine wave'), ('Điện áp một chiều không đổi', 'A constant dc voltage'), ('Xung kim', 'A train of spikes')], ('Tụ nạp–xả giữa +B·Vsat và −B·Vsat; mỗi lần chạm ngưỡng, bộ so sánh đổi mức nên ngõ ra là sóng vuông.', 'The capacitor charges and discharges between +B·Vsat and −B·Vsat; each time it reaches a threshold the comparator flips, so the output is a square wave.'), 1, F7, 'm07-relaxation')
# m08 heat
IR = 'IC regulators'; F8 = ('Floyd 9e §17–4', 'Floyd 9e §17–4')
Q('m08', IR, ('Bộ ổn áp tuyến tính có VIN = 12 V, VOUT = 5 V, IL = 0,5 A. Công suất tiêu tán (toả nhiệt) trên phần tử pass là bao nhiêu?', 'A linear regulator has VIN = 12 V, VOUT = 5 V, IL = 0.5 A. What power is dissipated as heat in the pass element?'),
  '3.5 W', ['6 W', '2.5 W', '8.5 W'], ('P_D = (VIN − VOUT)·IL = 7 × 0,5 = 3,5 W (không phải VIN·IL = 6 W).', 'P_D = (VIN − VOUT)·IL = 7 × 0.5 = 3.5 W (not VIN·IL = 6 W).'), 2, F8, 'm08-heat')
Q('m08', IR, ('Bộ ổn áp tuyến tính nhận 12 V và cho ra 5 V. Hiệu suất xấp xỉ (bỏ qua dòng tĩnh) là bao nhiêu?', 'A linear regulator takes 12 V and delivers 5 V. What is its approximate efficiency (neglecting quiescent current)?'),
  '41.7 %', ['58.3 %', '100 %', '71 %'], ('η ≈ VOUT/VIN = 5/12 = 41,7 %; phần còn lại (58,3 %) biến thành nhiệt.', 'η ≈ VOUT/VIN = 5/12 = 41.7 %; the other 58.3 % becomes heat.'), 2, F8, 'm08-heat')
