LV = 'Transducers: LVDT, RVDT, inductive, capacitive'; FL = ('EASA M04 SM03 p.3.4, 3.10', 'EASA M04 SM03 p.3.4, 3.10')
Q('m10', LV, ('Hai cuộn thứ cấp của một LVDT (nối ngược pha) cho 3,2 V và 1,8 V. Điện áp ngõ ra là bao nhiêu?', 'The two secondaries of an LVDT (connected in series opposition) give 3.2 V and 1.8 V. What is the output voltage?'),
  '1.4 V', ['5.0 V', '2.5 V', '0 V'], ('Ngõ ra là hiệu hai điện áp thứ cấp: 3,2 − 1,8 = 1,4 V; pha của nó cho biết lõi lệch về phía cuộn nào.', 'The output is the difference of the secondary voltages: 3.2 − 1.8 = 1.4 V; its phase tells on which side the core has moved.'), 1, FL, 'm10-lvdt')
Q('m10', LV, ('Một LVDT có độ nhạy 0,2 V/mm trong dải tuyến tính. Lõi lệch 3 mm khỏi tâm thì điện áp ngõ ra là bao nhiêu?', 'An LVDT has a sensitivity of 0.2 V/mm in its linear range. What is the output when the core is 3 mm off centre?'),
  '0.6 V', ['1.5 V', '0.067 V', '6 V'], ('Ngõ ra tuyến tính theo độ dời: 0,2 V/mm × 3 mm = 0,6 V.', 'The output is linear in displacement: 0.2 V/mm × 3 mm = 0.6 V.'), 1, FL, 'm10-lvdt')
Q('m10', LV, ('Ngõ ra của LVDT ở trên là 1,5 V với độ nhạy 0,2 V/mm (trong dải tuyến tính). Lõi lệch bao nhiêu milimét?', 'The LVDT above outputs 1.5 V with a sensitivity of 0.2 V/mm (linear range). How far is the core from the centre?'),
  '7.5 mm', ['0.3 mm', '3 mm', '75 mm'], ('Độ dời = ngõ ra/độ nhạy = 1,5 V / 0,2 V/mm = 7,5 mm.', 'Displacement = output/sensitivity = 1.5 V / 0.2 V/mm = 7.5 mm.'), 2, FL, 'm10-lvdt')
Q('m10', LV, ('Lõi LVDT nằm đúng tâm và mỗi cuộn thứ cấp cho 2,0 V. Điện áp ngõ ra hiệu là bao nhiêu và đây gọi là điểm nào?', 'The LVDT core is exactly centred and each secondary gives 2.0 V. What is the differential output and what is this position called?'),
  ('0 V, điểm không (null)', '0 V, the null position'), [('4,0 V, điểm bão hoà', '4.0 V, saturation'), ('2,0 V, điểm giữa', '2.0 V, mid-point'), ('1,0 V, điểm chuẩn', '1.0 V, reference')], ('Hai điện áp bằng nhau và ngược pha nên hiệu bằng 0: đó là điểm null.', 'The two voltages are equal and opposite so the difference is 0: the null position.'), 1, FL, 'm10-lvdt')
DC = 'Differential, control synchros and resolvers'; FC = ('EASA M04 SM03 pp.3.7–3.10', 'EASA M04 SM03 pp.3.7–3.10')
Q('m10', DC, ('Máy biến áp điều khiển (CT) cho điện áp sai số 0,15 V mỗi độ lệch góc (vùng góc nhỏ). Sai số góc 8° cho điện áp sai số là bao nhiêu?', 'A control transformer (CT) gives an error voltage of 0.15 V per degree of angular error (small-angle range). What error voltage does an 8° error give?'),
  '1.2 V', ['0.019 V', '12 V', '0.12 V'], ('Điện áp sai số tỉ lệ với sai số góc: 0,15 V/° × 8° = 1,2 V.', 'The error voltage is proportional to the angular error: 0.15 V/° × 8° = 1.2 V.'), 1, FC, 'm10-control-synchro')
Q('m10', DC, ('Với cùng độ nhạy 0,12 V/° của một CT, điện áp sai số đo được là 3,0 V. Sai số góc là bao nhiêu?', 'With a CT sensitivity of 0.12 V/°, the measured error voltage is 3.0 V. What is the angular error?'),
  '25°', ['0.36°', '2.5°', '250°'], ('Sai số góc = 3,0 V / 0,12 V/° = 25° (pha của điện áp cho biết chiều lệch).', 'Angular error = 3.0 V / 0.12 V/° = 25° (the phase of the voltage gives the direction).'), 2, FC, 'm10-control-synchro')
Q('m10', DC, ('Một synchro vi sai (TDX) nhận hai góc vào 40° và 25°. Góc ngõ ra khi nối bình thường và khi đảo hai dây S1–S3 của một ngõ vào là bao nhiêu?', 'A differential synchro (TDX) receives two input angles 40° and 25°. What is the output angle when wired normally and when two leads S1–S3 of one input are reversed?'),
  ('65° (cộng) và 15° (trừ)', '65° (sum) and 15° (difference)'), [('15° (cộng) và 65° (trừ)', '15° (sum) and 65° (difference)'), ('65° và 65°', '65° and 65°'), ('40° và 25°', '40° and 25°')], ('TDX cho tổng hai góc: 40° + 25° = 65°; đảo S1–S3 đổi dấu một góc nên được hiệu 40° − 25° = 15°.', 'The TDX gives the sum of the two angles: 40° + 25° = 65°; reversing S1–S3 negates one angle, giving the difference 40° − 25° = 15°.'), 2, FC, 'm10-control-synchro')
Q('m10', DC, ('Một resolver có điện áp kích thích đỉnh 10 V. Ở góc rôto 30°, hai ngõ ra sin và cos có biên độ đỉnh bao nhiêu?', 'A resolver is excited with 10 V peak. At a rotor angle of 30°, what are the peak amplitudes of the sine and cosine outputs?'),
  ('5,00 V và 8,66 V', '5.00 V and 8.66 V'), [('8,66 V và 5,00 V', '8.66 V and 5.00 V'), ('10 V và 10 V', '10 V and 10 V'), ('3,33 V và 6,67 V', '3.33 V and 6.67 V')], ('Ngõ ra sin = 10·sin 30° = 5,00 V; ngõ ra cos = 10·cos 30° = 8,66 V (hai cuộn lệch 90°).', 'Sine output = 10·sin 30° = 5.00 V; cosine output = 10·cos 30° = 8.66 V (windings 90° apart).'), 2, FR, 'm10-resolver')
Q('m10', DC, ('Một resolver cho ∝ sin θ = 0,866 và ∝ cos θ = 0,5. Góc rôto là bao nhiêu?', 'A resolver gives ∝ sin θ = 0.866 and ∝ cos θ = 0.5. What is the rotor angle?'),
  '60°', ['30°', '45°', '120°'], ('θ = atan2(0,866; 0,5) = 60°.', 'θ = atan2(0.866, 0.5) = 60°.'), 2, FR, 'm10-resolver')
Q('m10', SP, ('Xung PWM 24 V có chu kỳ làm việc 25 % đặt lên servomotor. Điện áp trung bình là bao nhiêu?', 'A 24 V PWM pulse train with a 25 % duty cycle drives a servomotor. What is the average voltage?'),
  '6 V', ['24 V', '18 V', '0.25 V'], ('Điện áp trung bình = duty × V = 0,25 × 24 = 6 V.', 'The average voltage = duty × V = 0.25 × 24 = 6 V.'), 1, FP, 'm10-pwm')
Q('m10', SP, ('Cần điện áp trung bình 9 V từ xung PWM 12 V. Chu kỳ làm việc phải bằng bao nhiêu?', 'An average voltage of 9 V is needed from 12 V PWM pulses. What duty cycle is required?'),
  '75 %', ['25 %', '9 %', '133 %'], ('duty = V_tb/V = 9/12 = 0,75 = 75 %.', 'duty = Vavg/V = 9/12 = 0.75 = 75 %.'), 1, FP, 'm10-pwm')
# m07 relaxation oscillator
R7b, C7b, R1b, R2b = 10e3, 22e-9, 30e3, 10e3; Bb = R2b / (R1b + R2b); f7b = 1 / (2 * R7b * C7b * math.log((1 + Bb) / (1 - Bb))); assert abs(Bb - 0.25) < 1e-12
Q('m07', RT, ('Bộ dao động thư giãn op-amp có R1 = 30 kΩ, R2 = 10 kΩ, Vsat = ±12 V. Hai ngưỡng của tụ là bao nhiêu?', 'An op-amp relaxation oscillator has R1 = 30 kΩ, R2 = 10 kΩ, Vsat = ±12 V. What are the two capacitor thresholds?'),
  '±3 V', ['±12 V', '±4 V', '±9 V'], ('B = R2/(R1 + R2) = 10/40 = 0,25; ngưỡng = ±B·Vsat = ±0,25 × 12 = ±3 V.', 'B = R2/(R1 + R2) = 10/40 = 0.25; thresholds = ±B·Vsat = ±0.25 × 12 = ±3 V.'), 2, F7, 'm07-relaxation')
Q('m07', RT, ('Với R1 = 30 kΩ, R2 = 10 kΩ (B = 0,25), R = 10 kΩ và C = 22 nF, tần số của bộ dao động thư giãn f = 1/(2RC·ln((1+B)/(1−B))) là bao nhiêu?', 'With R1 = 30 kΩ, R2 = 10 kΩ (B = 0.25), R = 10 kΩ and C = 22 nF, what is the relaxation oscillator frequency f = 1/(2RC·ln((1+B)/(1−B)))?'),
  f'{g(f7b / 1e3, 3)} kHz', [f'{g(1 / (2 * R7b * C7b) / 1e3, 3)} kHz', f'{g(1 / (2 * R7b * C7b * math.log(3)) / 1e3, 3)} kHz', f'{g(1 / (R7b * C7b * math.log((1 + Bb) / (1 - Bb))) / 1e3, 3)} kHz'],
  (f'ln(1,25/0,75) = 0,5108 nên f = 1/(2 × 10⁴ × 22·10⁻⁹ × 0,5108) = {g(f7b / 1e3, 3)} kHz.', f'ln(1.25/0.75) = 0.5108 so f = 1/(2 × 10⁴ × 22·10⁻⁹ × 0.5108) = {g(f7b / 1e3, 3)} kHz.'), 3, F7, 'm07-relaxation')
